using Etamid.Domain.Identity;

namespace Etamid.Application.Common.Interfaces;

/// <summary>Object storage for uploaded bytes. The key is generated by the application, never by the client.</summary>
public interface IFileStorage
{
    Task SaveAsync(string key, Stream content, CancellationToken cancellationToken);
}

/// <summary>Encrypts sensitive values at rest (IBAN) and produces a keyed hash for uniqueness checks.</summary>
public interface IFieldProtector
{
    string Protect(string plainText);
    string Unprotect(string protectedValue);
    string Hash(string value);
}

public sealed record NafathStartResult(string RandomNumber);

public sealed record NafathPollResult(NafathStatus Status, string? NationalId, string? FullName);

public interface INafathClient
{
    Task<NafathStartResult> StartAsync(string requestId, CancellationToken cancellationToken);
    Task<NafathPollResult> PollAsync(string requestId, DateTime startedAtUtc, CancellationToken cancellationToken);
}
